declare module '*.png' {
  const content: number;
  export default content;
}

declare module '*.jpg' {
  const content: number;
  export default content;
}

declare module '*.jpeg' {
  const content: number;
  export default content;
}

declare module '*.webp' {
  const content: number;
  export default content;
}

declare module '*.css';

/** Android vector drawable(Material Symbols). Metro가 에셋 번호로 준다 */
declare module '*.xml' {
  const content: number;
  export default content;
}
